houses = [{'nationality': 'Norwegian', 'color': None, 'pet': None, 'drink': None, ...}, {'nationality': 'Spaniard', 'color': 'b...', 'drink': 'orange juice', ...}, {'nationality': 'Ukrainian', 'color': 'yellow', 'pet': 'horse', 'drink': 'tea', ...}]

    def _verify(houses):
        """Return True if the complete assignment satisfies every clue."""

        def at(category, value):
            return [i for i, h in enumerate(houses) if h[category] == value]

        # Each category is a permutation of its five values.
        for category in CATEGORIES:
            values = [h[category] for h in houses]
            if len(set(values)) != 5:
                return False

        for h in houses:
            # 2. The Englishman lives in the red house.
            if h["nationality"] == "Englishman" and h["color"] != "red":
                return False
            # 3. The Spaniard owns the dog.
            if h["nationality"] == "Spaniard" and h["pet"] != "dog":
                return False
            # 4. The person in the green house drinks coffee.
            if h["color"] == "green" and h["drink"] != "coffee":
                return False
            # 5. The Ukrainian drinks tea.
            if h["nationality"] == "Ukrainian" and h["drink"] != "tea":
                return False
            # 7. The snail owner likes to go dancing.
            if h["pet"] == "snail" and h["hobby"] != "dancing":
                return False
            # 8. The person in the yellow house is a painter.
            if h["color"] == "yellow" and h["hobby"] != "painting":
                return False
            # 13. The person who plays football drinks orange juice.
            if h["hobby"] == "football" and h["drink"] != "orange juice":
                return False
            # 14. The Japanese person plays chess.
            if h["nationality"] == "Japanese" and h["hobby"] != "chess":
                return False

        # 6. The green house is immediately to the right of the ivory house.
